class Solution {
public:
    vector<int> shortestToChar(string s, char c) {
        int n = s.length();
        vector<int> ans(n, 1e9);
        int prev = -1e9;
        for (int i = 0; i < n; i++) {
            if (s[i] == c) prev = i;
            ans[i] = i - prev;
        }
        prev = 1e9;
        for (int i = n - 1; i >= 0; i--) {
            if (s[i] == c) prev = i;
            ans[i] = min(ans[i], prev - i);
        }
        return ans;
    }
};

class Solution {
    public int[] shortestToChar(String s, char c) {
        int n = s.length();
        int[] ans = new int[n];
        int prev = -100000;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == c) prev = i;
            ans[i] = i - prev;
        }
        prev = 100000;
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == c) prev = i;
            ans[i] = Math.min(ans[i], prev - i);
        }
        return ans;
    }
}

var shortestToChar = function(s, c) {
    const n = s.length;
    const ans = new Array(n).fill(Infinity);
    let prev = -Infinity;
    for (let i = 0; i < n; i++) {
        if (s[i] === c) prev = i;
        ans[i] = i - prev;
    }
    prev = Infinity;
    for (let i = n - 1; i >= 0; i--) {
        if (s[i] === c) prev = i;
        ans[i] = Math.min(ans[i], prev - i);
    }
    return ans;
};
